USE KEY_IRASV5_Upstream

select * from dbo.AIRegulated

-- NEW SEARCH AND REPLACE FUNCTION
--SELECT dbo.REGEXP_REPLACE('ABC_DEF_1234','(?<prefix>[a-zA-Z_]+)(?<number>\d+)','${prefix}____${number}____');
--SELECT dbo.REGEXP_REPLACE('this is a test LastModDateTime is test LastModDate','LastModDate$','LastModDateTime')
--SELECT REPLACE ('this is a test LastModDateTime is test LastModDate','LastModDate>','LastModDateTime')

-- columns that need to be renamed or dropped

SELECT DISTINCT(column_name) 
FROM INFORMATION_SCHEMA.columns 
WHERE (column_name LIKE 'Create%User%' OR 
	column_name LIKE N'LastMod%User%' OR 
	column_name LIKE N'Create%Date%' OR 
	column_name LIKE N'LastMod%Date%')
AND column_name NOT IN ('CreatedUser', 'LastModByUserId', 'CreatedDate', 'LastModDateTime')

SELECT DISTINCT(col.name) AS column_name
FROM sys.tables tab 
INNER JOIN sys.columns col
	ON tab.object_id = col.object_id
WHERE (col.name LIKE 'LastMod%' OR 
	col.name LIKE 'Create%')
	AND col.name NOT IN ('CreatedUser', 'LastModByUserId', 'CreatedDate', 'LastModDateTime')

-- Find the different variations of row tracking columns among tables

SELECT DISTINCT(col.name) AS column_name
FROM sys.tables tab 
INNER JOIN sys.columns col
	ON tab.object_id = col.object_id
WHERE (col.name LIKE 'LastMod%' OR 
	col.name LIKE 'Create%')
GO
-- Find the different variations of row tracking columns among tables AND views
SELECT DISTINCT(column_name) FROM INFORMATION_SCHEMA.columns 
WHERE (column_name LIKE 'LastMod%' OR 
	column_name LIKE 'Create%')
GO

-- columns that need to be dropped or renamed
SELECT DISTINCT(col.name) AS column_name
FROM sys.tables tab 
INNER JOIN sys.columns col
	ON tab.object_id = col.object_id
WHERE (col.name LIKE 'LastMod%' OR 
	col.name LIKE 'Create%')
	AND col.name NOT IN ('CreatedDate', 'CreatedUser', 'LastModByUserId', 'LastModDateTime')
GO

-- tables without the specified column
SELECT name AS table_name FROM sys.tables
EXCEPT
(
SELECT tab.name AS table_name 
FROM sys.tables tab
JOIN sys.columns col
ON tab.object_id = col.object_id
WHERE col.name LIKE 'Create%Date%'
UNION
SELECT tab.name AS table_name 
FROM sys.tables tab
JOIN sys.columns col
ON tab.object_id = col.object_id
WHERE col.name LIKE 'Create%User%'
UNION
SELECT tab.name AS table_name 
FROM sys.tables tab
JOIN sys.columns col
ON tab.object_id = col.object_id
WHERE col.name LIKE 'LastMod%Date%'
UNION
SELECT tab.name AS table_name 
FROM sys.tables tab
JOIN sys.columns col
ON tab.object_id = col.object_id
WHERE col.name LIKE 'LastMod%User%')
GO
-- tables AND views without the specified column
SELECT ist.table_name, table_type FROM INFORMATION_SCHEMA.TABLES ist
JOIN 
(
SELECT table_name AS table_name FROM INFORMATION_SCHEMA.COLUMNS
EXCEPT
(
SELECT table_name AS table_name 
FROM INFORMATION_SCHEMA.COLUMNS
WHERE column_name LIKE 'Create%' 
AND column_name LIKE 'LastMod%')) subq
ON subq.table_name = ist.table_name
GO

-- Get tables and columns in each table or view that need to be modified
SELECT table_name, column_name
FROM INFORMATION_SCHEMA.COLUMNS
WHERE (column_name LIKE 'Create%'
       OR column_name LIKE 'LastMod%')
	AND table_name = 'INCIDENT' 

-- number of duplicate columns for the specified search string regEx 
SELECT tab.name AS table_name, count(*)
FROM sys.tables tab
JOIN sys.columns col
ON tab.object_id = col.object_id
Where col.name LIKE 'Create%User%' --OR
		--col.name LIKE 'LastMod%'
 --AND c.table_name = 'COUPON'
GROUP BY tab.name
HAVING COUNT(*) > 1

-- Find all triggers on tables/views that need to be modified

SELECT DISTINCT(trig.object_id) AS trigger_id, name AS trigger_name, subq.table_name
FROM sys.triggers trig
JOIN 
(SELECT trig.object_id AS trig_id,
	   trig.name AS trigger_name,
	   isc.table_name, 
	   isc.column_name
FROM INFORMATION_SCHEMA.COLUMNS isc
INNER JOIN sys.triggers trig
	ON OBJECT_ID(isc.table_name) = trig.parent_id
WHERE (column_name LIKE 'LastMod%' OR
      column_name LIKE 'Create%')
	  ) subq
ON subq.trig_id = trig.object_id
--WHERE trigger_name = 'td_rectifier'
GO

select * from sys.procedures

-- Drop Default Constraints on a table's column

DECLARE @ConstraintName NVARCHAR(200)
DECLARE @DefaultConstrList TABLE (id INT IDENTITY(1,1) PRIMARY KEY CLUSTERED, cons_name VARCHAR(100))
SELECT @ConstraintName = cons.name FROM SYS.DEFAULT_CONSTRAINTS cons
WHERE parent_object_id = OBJECT_ID('INCIDENT')
AND parent_column_id IN (SELECT column_id FROM sys.columns col
                        WHERE col.name LIKE N'Create%User%'
                        AND object_id = OBJECT_ID(N'INCIDENT'))
						SELECT * from @DefaultConstrList
IF @ConstraintName IS NOT NULL
EXEC('ALTER TABLE INCIDENT DROP CONSTRAINT ' + @ConstraintName)

-- find the default functions on a table
SELECT tab.name AS table_name,
      col.name AS column_name,
	  con.name AS constraint_name
FROM sys.tables tab
INNER JOIN sys.columns col 
ON tab.object_id = col.object_id
LEFT JOIN sys.default_constraints con
ON con.parent_column_id = col.column_id
WHERE col.name LIKE 'Create%User%' 
	AND tab.name = 'INCIDENT'
ORDER BY 3

IF OBJECT_ID('SchemaName.MyConstraint', 'D') IS NULL

-- Finds all tables (excludes views) with the specified column

SELECT tab.object_id, tab.name, col.name
FROM sys.tables tab
INNER JOIN sys.columns col 
ON tab.object_id = col.object_id
WHERE (col.name LIKE 'Create%Date%' OR
		col.name LIKE 'LastMod%')
GO

-- finds information on tables (excludes views)
SELECT * FROM INFORMATION_SCHEMA.TABLES
WHERE table_type = 'BASE TABLE'

-- Table with atleast 1 create date column

SELECT tab.name AS table_name, col.name AS column_name
FROM sys.tables tab
JOIN sys.columns col
ON tab.object_id = col.object_id
WHERE col.name LIKE 'Create%Date%'

SELECT DISTINCT(name) AS table_name FROM sys.tables
	EXCEPT
	(SELECT tab.name AS table_name 
	FROM sys.tables tab
	JOIN sys.columns col
	ON tab.object_id = col.object_id
	WHERE col.name LIKE N'LastMod%Date%');

